import{_ as e,o as i,c as t,a1 as n}from"./chunks/framework.CblolBb6.js";const k=JSON.parse('{"title":"Hari 4 - Penyempurnaan dan Studi Kasus","description":"","frontmatter":{},"headers":[],"relativePath":"hari-4/index.md","filePath":"hari-4/index.md"}'),r={name:"hari-4/index.md"};function s(d,a,u,l,m,p){return i(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="hari-4-penyempurnaan-dan-studi-kasus" tabindex="-1">Hari 4 - Penyempurnaan dan Studi Kasus <a class="header-anchor" href="#hari-4-penyempurnaan-dan-studi-kasus" aria-label="Permalink to &quot;Hari 4 - Penyempurnaan dan Studi Kasus&quot;">​</a></h1><p>Hari keempat menutup pelatihan. Aplikasi yang sudah berjalan di server disempurnakan, satu teknik visualisasi baru ditambahkan, lalu seluruh alur WebGIS ditinjau ulang bersama.</p><h2 id="jadwal-hari-4" tabindex="-1">Jadwal Hari 4 <a class="header-anchor" href="#jadwal-hari-4" aria-label="Permalink to &quot;Jadwal Hari 4&quot;">​</a></h2><p>Mengacu pada susunan acara pelatihan periode 15 sampai 18 September 2026.</p><table tabindex="0"><thead><tr><th>Waktu</th><th>Kegiatan</th><th>Materi di halaman ini</th></tr></thead><tbody><tr><td>08.00 - 10.00</td><td>Penyempurnaan WebGIS</td><td>Belum tersedia</td></tr><tr><td>10.15 - 11.30</td><td>Implementasi data Gaussian Splatting</td><td>Belum tersedia</td></tr><tr><td>13.30 - 15.00</td><td>Review alur WebGIS dan diskusi</td><td>Belum tersedia</td></tr><tr><td>15.00 - 15.30</td><td>Post-Test</td><td>Tidak memerlukan materi</td></tr><tr><td>15.30 - 16.15</td><td>Penutupan Pelatihan</td><td>Tidak memerlukan materi</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Seluruh materi Hari 4 belum tersedia</p><p>Belum ada berkas materi untuk Hari 4 di repositori ini. Seluruh sesi pada hari tersebut saat ini disampaikan langsung oleh instruktur. Halaman ini akan diperbarui begitu materinya tersedia.</p><p>Status ini dicatat apa adanya supaya peserta tidak menyimpulkan bahwa halamannya hilang atau tautannya rusak.</p></div><h2 id="gambaran-sesi" tabindex="-1">Gambaran Sesi <a class="header-anchor" href="#gambaran-sesi" aria-label="Permalink to &quot;Gambaran Sesi&quot;">​</a></h2><p>Bagian ini menjelaskan apa yang dikerjakan pada tiap sesi, tanpa memuat langkah teknis. Langkah teknisnya menyusul setelah materinya tersedia.</p><p><strong>Penyempurnaan WebGIS.</strong> Peserta meninjau kembali aplikasi yang sudah berjalan dan memperbaiki bagian yang belum selesai. Cakupannya bergantung pada keadaan tiap peserta, sehingga instruktur menetapkan prioritas pada awal sesi.</p><p><strong>Implementasi data Gaussian Splatting.</strong> Sesi ini menambahkan satu cara baru menampilkan objek 3D, yaitu Gaussian Splatting, sebagai pelengkap 3D Tiles yang sudah dikerjakan pada Hari 2. Bentuk datanya berbeda, dan cara memuatnya di CesiumJS juga berbeda.</p><p><strong>Review alur WebGIS dan diskusi.</strong> Seluruh rantai kerja ditinjau ulang: data spasial diolah, disimpan di basis data, disajikan GeoServer, ditampilkan di web sebagai peta 2D dan 3D, diamankan dengan autentikasi, lalu dijalankan di server. Sesi ini menutup rangkaian tersebut menjadi satu gambaran utuh.</p><h2 id="yang-sudah-dimiliki-peserta-sebelum-hari-4" tabindex="-1">Yang Sudah Dimiliki Peserta Sebelum Hari 4 <a class="header-anchor" href="#yang-sudah-dimiliki-peserta-sebelum-hari-4" aria-label="Permalink to &quot;Yang Sudah Dimiliki Peserta Sebelum Hari 4&quot;">​</a></h2><p>Setelah Hari 1 sampai Hari 3, peserta sudah memiliki:</p><ul><li>Repositori GitHub berisi proyek Next.js, terhubung ke Cloud Build.</li><li>Basis data PostgreSQL dengan PostGIS, dan GeoServer yang menyajikan layernya.</li><li>Geoportal yang berjalan di alamat HTTPS dengan subdomain sendiri.</li><li>Sistem login dan hak akses berbasis NextAuth.</li></ul>',14)])])}const o=e(r,[["render",s]]);export{k as __pageData,o as default};
